function validate([flowers]) {
  if (flowers.length < 2 || flowers.length > 100000) return 'flowers needs 2 to 10^5 values.';
  if (!flowers.every(v => Number.isInteger(v) && v >= -10000 && v <= 10000)) return 'Each beauty is an integer from -10^4 to 10^4.';
  if (new Set(flowers).size === flowers.length) return 'Some value must appear at least twice so a valid garden exists.';
  return null;
}

