function maximumBeauty(flowers) {
  const firstPrefix = new Map();
  let prefix = 0;
  let best = -Infinity;

  for (const flower of flowers) {
    if (firstPrefix.has(flower)) {
      const beauty = 2 * flower + prefix - firstPrefix.get(flower);
      best = Math.max(best, beauty);
    }
    prefix += Math.max(flower, 0);
    if (!firstPrefix.has(flower)) {
      firstPrefix.set(flower, prefix);
    }
  }
  return best;
}

