function maximumBeauty(flowers) {
  let answer = null;
  for (let i = 0; i < flowers.length; i++)
    for (let j = i + 1; j < flowers.length; j++) {
      if (flowers[i] !== flowers[j]) continue;
      let total = flowers[i] + flowers[j];
      for (let k = i + 1; k < j; k++) if (flowers[k] > 0) total += flowers[k];
      if (answer === null || total > answer) answer = total;
    }
  return answer;
}

