function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : int(2, 10);
  const span = size === 'large' ? (rand() < 0.5 ? 10000 : 60) : (rand() < 0.5 ? 3 : 12);
  const flowers = Array.from({ length: n }, () => int(-span, span));
  // A valid garden must exist, so copy one flower's value onto another position.
  const i = int(0, n - 1);
  let j = int(0, n - 2);
  if (j >= i) j++;
  flowers[j] = flowers[i];
  return [flowers];
}
